(() => {
 'use strict';
 const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const state={user:null,data:null,tab:'overview',security:null,filters:{},loading:false,timezones:null,scheduleEditor:null,contests:null,views:{}};
 const sections=LCPCNavigation.sections;
 const manage=()=>['owner','operator'].includes(state.user?.role),owner=()=>state.user?.role==='owner';
 let toastTimer,clockSample=null;
 function notice(message,error=false){clearTimeout(toastTimer);$('notice').textContent=message;$('notice').className='toast'+(error?' error':'');$('notice').hidden=false;toastTimer=setTimeout(()=>$('notice').hidden=true,6500);}
 async function api(path,data){const options={credentials:'same-origin',cache:'no-store',headers:{}};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':state.user?.csrf||''};options.body=JSON.stringify({...data,contestId:state.data?.system?.contestId||state.contests?.selected});}const response=await fetch('/api/'+path,options);const value=await response.json();if(!response.ok){if(response.status===401&&path!=='login')signedOut();throw new Error(value.error||'Request failed');}if(path==='snapshot')state.clockServerDate=response.headers.get('Date');return value;}
 function signedOut(){clockSample=null;LCPCLearningReports.dispose();LCPCParticipantActivity.dispose();LCPCOrganizerScoreboards.dispose();LCPCParticipantIdentityEditor.dispose();LCPCTeamConnections.stop();LCPCNotifications.stop();state.scheduleEditor?.dispose();state.scheduleEditor=null;state.timezones=null;state.contests=null;state.user=null;state.data=null;$('sidebar-server-ip').textContent='Connecting…';$('sidebar-last-updated').textContent='Waiting for data';$('sidebar-last-updated').removeAttribute('datetime');$('quick-clock').hidden=true;$('workspace').hidden=true;$('login-screen').hidden=false;$('modal').close();document.getElementById('row-details-dialog')?.close();$('login-form').reset();}
 function navigation(){const nav=$('navigation'),position=nav.scrollTop;nav.replaceChildren();let lastGroup='';for(const [id,icon,label,group] of sections){const query=$('navigation-search').value.trim().toLowerCase();if(query&&!label.toLowerCase().includes(query)&&!group.toLowerCase().includes(query))continue;if(['security','system'].includes(id)&&!owner())continue;if(state.user.mustChange&&id!=='account')continue;if(group!==lastGroup){const heading=document.createElement('p');heading.className='nav-group';heading.textContent=group;nav.append(heading);lastGroup=group;}const button=document.createElement('button');button.type='button';button.dataset.tab=id;button.classList.toggle('active',state.tab===id);button.innerHTML='<span class="nav-icon" aria-hidden="true">'+LCPCNavigation.icon(icon)+'</span>'+label;nav.append(button);}nav.scrollTop=position;}
 function activeView(){return LCPCNavigation.current(state.tab,state.views[state.tab],owner());}
 function sectionTabs(){const items=LCPCNavigation.available(state.tab,owner());if(items.length<2)return '';const active=activeView();return '<nav class="section-tabs" aria-label="'+esc(sections.find(x=>x[0]===state.tab)?.[2]||'Section')+' tools">'+items.map(([id,label])=>'<button type="button" data-section-view="'+esc(id)+'" aria-current="'+(id===active?'page':'false')+'"'+(id===active?' class="active"':'')+'>'+esc(label)+'</button>').join('')+'</nav>';}
 function nativeContext(){return {api,dialog,close:closeModal,notice,download:downloadPost,save:saveBlob,file64,user:state.user,data:state.data,getData:()=>state.data,refresh:()=>refresh(),date,table,openTestSubmissions:()=>{state.filters={account:'test'};state.tab='runs';state.views.runs='main';render();window.scrollTo(0,0);},navigate:(page,view='main')=>{if(!sections.some(([id])=>id===page)||!LCPCNavigation.available(page,owner()).some(([id])=>id===view)&&view!=='main')return;state.tab=page;state.views[page]=view;render();window.scrollTo(0,0);}};}
 function signedIn(user){state.user=user;state.tab=user.mustChange?'account':'overview';$('login-screen').hidden=true;$('workspace').hidden=false;$('user-badge').textContent=user.username+' · '+user.role;navigation();render();if(!user.mustChange)refresh();}
 async function refresh(silent=false){if(!state.user||state.user.mustChange||state.loading)return;state.loading=true;try{state.contests=await api('contests');state.data=await api('snapshot');updateSidebar();LCPCNotifications.start(nativeContext());const warning=$('workspace-warning'),sys=state.data.system;document.querySelector('.sidebar-bottom p').textContent=sys.pc2Connected?'Java / PC² connected':sys.contestStatus==='draft'?'Draft workspace':'PC² offline';warning.hidden=sys.contestStatus==='active';warning.textContent=sys.contestStatus==='draft'?'Draft workspace: changes prepare this contest only. Participant access stays with the active contest.':sys.contestStatus==='archived'?'Archived contest: retained data is available for reports and backups. Unarchive before editing.':'Offline workspace: live PC² controls are unavailable until activation.';if(!state.timezones)state.timezones=await api('timezones');$('connection-error').hidden=true;const c=state.data.contest;try{clockSample=LCPCContestClock.sample({clock:{schema:1,...c},publishedAt:state.data.updatedAt},{serverDate:state.clockServerDate,now:performance.now()});}catch(_){clockSample=null;}updateClockBadge();if(state.tab==='security'&&owner())state.security=await api('security');if(!silent||(!$('native-admin')&&!$('participant-activity')&&!$('participant-test')&&!$('team-connections')&&!$('remote-access')&&!$('dashboard-branding')&&!$('participant-identity')&&!$('learning-reports')&&!$('organizer-scoreboard')&&!$('platform-guide')&&!$('platform-about')&&!document.querySelector('dialog[open]')&&!$('content').contains(document.activeElement)&&!document.querySelector('#contest-form[data-dirty="true"]')))render();}catch(error){$('connection-error').textContent=error.message;$('connection-error').hidden=false;$('sidebar-refresh-status').hidden=false;if(['contests','controls'].includes(state.tab))render();if(!silent)notice(error.message,true);}finally{state.loading=false;}}
 function updateClockBadge(){if(!state.user||!state.data)return;const kind=state.data.system.contestStatus,v=LCPCContestClock.workspaceView(state.data.contest,kind,clockSample,performance.now());const badge=$('clock-badge');const text=v.status+' · '+v.text,cls='badge '+(v.stale?'pending':v.low?'clock-low':kind==='active'&&clockSample?.running?'accepted':'pending');if(badge.textContent!==text)badge.textContent=text;if(badge.className!==cls)badge.className=cls;}
 setInterval(updateClockBadge,250);
 function updateSidebar(){$('quick-clock').hidden=!!state.user?.mustChange;const info=state.data.system.serverAccess||state.data.system.participantAccess;$('sidebar-server-ip').textContent=info?.assigned?info.ip:info?.active?'Unavailable':'No active server';$('sidebar-last-updated').textContent=date(info?.checkedAt||state.data.updatedAt);$('sidebar-last-updated').dateTime=info?.checkedAt||state.data.updatedAt||'';$('sidebar-refresh-status').hidden=true;}
 function clock(seconds){seconds=Math.max(0,Math.floor(seconds||0));return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');}
 function date(value){if(!value)return '—';const instant=new Date(typeof value==='number'?value*1000:value);try{return instant.toLocaleString('en-GB',{timeZone:state.data?.system?.timezone||'Africa/Tripoli',hour12:false});}catch(_){return instant.toLocaleString('en-GB',{timeZone:'UTC',hour12:false})+' UTC';}}
 function status(verdict){const v=String(verdict||'Pending').replace(/^No\s*[-–:]\s*/i,'');if(/^(yes|correct|accepted)$/i.test(v))return ['Accepted','accepted'];if(/^no$/i.test(v))return ['Wrong Answer','rejected'];if(/pending|judging|queued|awaiting/i.test(v))return ['Pending','pending'];return [v,'rejected'];}
 const workflowLabels={automatic:'Automatic only',review:'Automatic + human approval',human:'Human only',mixed:'Mixed per-problem settings'};
 function verdictCell(r){return (r.testAccount?'<span class="badge neutral">Test account</span><br>':'')+badge(r.verdict)+(!r.final&&r.automaticVerdict?'<br><small>Provisional: '+esc(status(r.automaticVerdict)[0])+'</small>':'');}
 function badge(value){const [label,type]=status(value);return '<span class="badge '+type+'">'+esc(label)+'</span>';}
 function button(action,label,id='',type='secondary'){return '<button type="button" class="compact '+type+'" data-action="'+action+'" data-id="'+esc(id)+'">'+esc(label)+'</button>';}
 function table(head,rows){return '<div class="table-wrap"><table><thead><tr>'+head.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+head.length+'" class="empty">No records to display.</td></tr>')+'</tbody></table></div>';}
 function option(value,label,selected){return '<option value="'+esc(value)+'"'+(String(value)===String(selected)?' selected':'')+'>'+esc(label)+'</option>';}
 function field(name,label,value='',type='text',extra=''){return '<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';}
 function check(name,label,value){return '<label><input type="checkbox" name="'+name+'"'+(value?' checked':'')+'>'+label+'</label>';}
 function panel(title,body,subtitle=''){return '<section class="panel"><div class="panel-heading"><div><h2>'+title+'</h2>'+(subtitle?'<p>'+subtitle+'</p>':'')+'</div></div>'+body+'</section>';}
 function overview(){const d=state.data,r=d.runs.filter(r=>!r.deleted&&!r.testAccount);const solved=r.filter(r=>r.final&&r.accepted).length,pending=r.filter(r=>!r.final).length;let html='<div class="stats">'+[[d.teams.filter(t=>!t.testAccount).length,'Teams',d.teams.filter(t=>t.online&&!t.testAccount).length+' online'],[r.length,'Submissions','All contest attempts'],[solved,'Accepted submissions','Across '+d.problems.length+' problems'],[pending,'Pending','Waiting for final verdicts']].map(([n,label,note])=>'<div class="stat"><span>'+label+'</span><strong>'+n+'</strong><small>'+note+'</small></div>').join('')+'</div>';
 const recent=r.slice().sort((a,b)=>b.number-a.number).slice(0,7);html+='<div class="grid-two">'+panel('Recent submissions',recentTable(recent),esc(d.contest.title))+panel('Contest status','<dl class="status-list"><dt>Clock</dt><dd>'+badge(d.contest.running?'Accepted':'Pending').replace('Accepted','Running').replace('Pending','Paused')+'</dd><dt>Remaining</dt><dd>'+clock(d.contest.remainingSeconds)+'</dd><dt>Duration</dt><dd>'+clock(d.contest.lengthSeconds)+'</dd><dt>Public freeze</dt><dd>'+esc(d.contest.freezeRemaining)+' remaining</dd><dt>Admin standings</dt><dd>Full results · no freeze</dd><dt>Control channel</dt><dd>Local Java / PC²</dd><dt>Last update</dt><dd>'+date(d.updatedAt)+'</dd></dl>')+'</div>';
 if(owner()){const a=d.system.participantAccess;html+=panel('Team access & testing','<p class="hint">Current server IP: <strong>'+esc(a?.assigned?a.ip:'No assigned managed address')+'</strong></p>'+(a?.origin?'<p><a href="'+esc(a.origin+'/#/login')+'" target="_blank" rel="noopener noreferrer">'+esc(a.origin+'/#/login')+'</a></p>':'')+button('server-controls-open','Server controls','','primary')+' '+button('participant-test-open','Open test & access center'));}
 html+=panel('Human review',reviewHelp()+button('review-queue','Open pending review ('+r.filter(x=>!x.final&&/^Awaiting human/.test(x.workflowState||'')).length+')','','primary'));
 html+=panel('Problem activity',d.problems.map(p=>{const attempts=r.filter(x=>x.problemId===p.id);return '<div class="progress-row"><span class="badge neutral">'+esc(p.letter)+'</span><span class="name">'+esc(p.name)+'</span><small>'+attempts.filter(x=>x.accepted).length+' accepted / '+attempts.length+' attempts</small></div>';}).join(''));return html;}
 function recentTable(rows){return table(['Run','Team','Problem','Verdict'],rows.map(r=>'<tr><td>'+button('run-details','#'+r.number,r.site+'-'+r.number)+'</td><td title="'+esc(r.teamName)+'">'+esc(r.teamName)+'</td><td title="'+esc(r.problem)+'">'+esc(r.problem)+'</td><td>'+verdictCell(r)+'</td></tr>')).replace('<table>','<table class="recent-runs">');}
 function runTable(rows){return table(['Run','Team','Problem','Language','Contest min','Verdict',''],rows.map(r=>'<tr><td>#'+r.number+'</td><td title="'+esc(r.teamName)+'">'+esc(r.teamName)+'<br><small>'+esc(r.team)+'</small></td><td title="'+esc(r.problem)+'">'+esc(r.problem)+'</td><td>'+esc(r.language)+'</td><td>'+Number(r.elapsedMinutes).toFixed(2)+'</td><td>'+verdictCell(r)+'</td><td>'+button('run-details','View details',r.site+'-'+r.number)+'</td></tr>'));}
 function runs(){const f=state.filters;let rows=state.data.runs.filter(r=>!r.deleted&&(f.account==='test'?r.testAccount:f.account==='all'?true:!r.testAccount)).sort((a,b)=>b.number-a.number);if(f.team)rows=rows.filter(r=>r.team===f.team);if(f.problem)rows=rows.filter(r=>r.problemId===f.problem);if(f.verdict)rows=rows.filter(r=>f.verdict==='review'?/^Awaiting human/.test(r.workflowState||''):status(r.verdict)[1]===f.verdict);return '<div class="split-heading"><div><h2>Submissions</h2><p>Click a submission row to review its source, automatic verdict and final human decision.</p></div>'+button('review-queue','Awaiting human ('+state.data.runs.filter(r=>!r.deleted&&!r.final&&!r.testAccount&&/^Awaiting human/.test(r.workflowState||'')).length+')','','primary')+'</div>'+reviewHelp()+'<form id="run-filters" class="filters"><label>Accounts<select name="account">'+option('','Official teams',f.account)+option('test','Test account only',f.account)+option('all','All accounts',f.account)+'</select></label><label>Team<select name="team">'+option('','All teams',f.team)+state.data.teams.filter(t=>f.account==='all'||(f.account==='test'?t.testAccount:!t.testAccount)).map(t=>option(t.login,t.name,f.team)).join('')+'</select></label><label>Problem<select name="problem">'+option('','All problems',f.problem)+state.data.problems.map(p=>option(p.id,p.letter+' · '+p.name,f.problem)).join('')+'</select></label><label>Verdict<select name="verdict">'+option('','All verdicts',f.verdict)+option('accepted','Accepted',f.verdict)+option('pending','Pending',f.verdict)+option('review','Awaiting human',f.verdict)+option('rejected','Unsuccessful',f.verdict)+'</select></label><button type="submit">Apply</button><button type="button" data-action="clear-filters">Clear</button></form>'+runTable(rows);}
 function teams(){return (owner()?panel('Private diagnostic account','<p class="hint">Each contest has an organizer test team excluded from official standings and counts.</p>'+button('participant-test-open','Test account & access')):'')+'<div class="split-heading"><div><h2>Team accounts</h2><p>Display names, login access and public standings visibility.</p></div>'+(manage()?button('team-create','Add team','','primary'):'')+'</div>'+table(['Account','Display name','Connection','Login','Scoreboard',''],state.data.teams.filter(t=>!t.testAccount).map(t=>'<tr><td>'+esc(t.login)+'</td><td>'+esc(t.name)+'</td><td><span class="badge '+(t.online?'accepted':'neutral')+'">'+(t.online?'Online':'Offline')+'</span></td><td>'+(t.enabled?'Enabled':'Disabled')+'</td><td>'+(t.visible?'Visible':'Hidden')+'</td><td>'+(manage()?button('team-edit','Edit',t.login):'')+'</td></tr>'));}
 function balloonFields(p={}){const rgb=/^#[0-9a-f]{6}$/i.test(p.colorRGB||'')?p.colorRGB:'#ffffff';return field('colorName','Balloon color name',p.colorName||'','text',(p.id&&!p.colorName?'':'required ')+'maxlength="80" placeholder="e.g. Red"')+field('colorRGB','Balloon color',rgb,'color','required');}
 function balloonCell(p){const color=/^#[0-9a-f]{6}$/i.test(p.colorRGB||'')?p.colorRGB:null;return color?'<span class="problem-balloon"><input type="color" value="'+esc(color)+'" disabled aria-label="'+esc(p.colorName||color)+' balloon color"><span>'+esc(p.colorName||color)+'</span></span>':p.colorName?esc(p.colorName):'<span class="hint">Not assigned</span>';}
 function rowDetails(row){
  const native=LCPCAdministrator.readRowDetails(row);if(native)return native;
  const control=row.querySelector('[data-action="problem-resources"]'),p=control&&state.data?.problems.find(p=>p.id===control.dataset.id);if(!p)return null;
  return {title:p.letter+' · '+p.name,detailsUrl:'/review.html?'+new URLSearchParams({contestId:state.data.system.contestId,problemId:p.id}),fields:[{label:'Problem',value:p.letter},{label:'Name',value:p.name},{label:'Difficulty',value:Number.isInteger(p.difficulty)?(p.difficultyEstimated?'≈':'')+String(p.difficulty):'Not assigned'},{label:'Balloon',value:p.colorName||p.colorRGB||'Not assigned',color:p.colorRGB},{label:'Time limit',value:p.timeLimit+' seconds'},{label:'Memory limit',value:p.memoryLimit+' MiB'},{label:'Judge tests',value:String(p.tests)},{label:'Status',value:p.active?'Active':'Inactive'}]};
 }
 function problems(){return '<div class="split-heading"><div><h2>Contest problems</h2><p>Judge settings are managed separately from participant statements and supporting files.</p></div>'+(owner()?button('problem-create','Add judged problem','','primary'):'')+'</div>'+table(['ID','Name','Difficulty','Balloon','Time limit','Memory','Judge tests','Status',''],state.data.problems.map(p=>'<tr><td>'+esc(p.letter)+'</td><td title="'+esc(p.name)+'">'+esc(p.name)+'</td><td title="'+(p.difficultyEstimated?'Estimated difficulty':'Problem difficulty')+'">'+(Number.isInteger(p.difficulty)?(p.difficultyEstimated?'≈':'')+esc(p.difficulty):'—')+'</td><td>'+balloonCell(p)+'</td><td>'+p.timeLimit+' s</td><td>'+p.memoryLimit+' MB</td><td>'+p.tests+'</td><td><span class="badge '+(p.active?'accepted':'neutral')+'">'+(p.active?'Active':'Inactive')+'</span></td><td>'+(manage()?button('problem-edit','Edit settings',p.id)+' ':'')+button('problem-resources','Resources',p.id)+'</td></tr>')).replace('<table>','<table class="problems-table">');}
 function resources(){const selected=state.filters.resourceProblem||'';let rows=state.data.resources;if(selected)rows=rows.filter(r=>r.problem===selected);const name=id=>id==='__contest__'?'Contest booklet':state.data.problems.find(p=>p.id===id)?.name||id;
 return '<div class="split-heading"><div><h2>Problem resources</h2><p>English and Arabic statements, contest booklets and supporting attachments.<br>Uploads start as drafts. Publishing a statement replaces the published version for that language.</p></div>'+(manage()?button('resource-trash','Removed files')+' '+button('upload','Upload resource','','primary'):'')+'</div><form id="resource-filter" class="filters"><label>Linked problem<select name="resourceProblem">'+option('','All resources',selected)+option('__contest__','Contest booklet',selected)+state.data.problems.map(p=>option(p.id,p.letter+' · '+p.name,selected)).join('')+'</select></label><button type="submit">Apply</button></form>'+(!rows.length?'<div class="panel empty">No resources for this selection.</div>':rows.map(r=>'<article class="resource-group panel"><div class="panel-heading"><div><h3>'+esc(r.label)+'</h3><small>'+esc(name(r.problem))+'</small></div><span class="badge '+(r.published?'accepted':'neutral')+'">'+(r.published?'Published':'Draft')+'</span></div><p class="resource-meta">'+esc(r.filename)+' · '+esc(r.kind)+' · '+esc(r.language.toUpperCase())+' · '+(r.size/1024).toFixed(1)+' KiB · Version '+r.version+'<br>SHA-256: '+esc(r.sha256)+'</p><div class="resource-actions">'+button('resource-download','Download',r.id)+(manage()?button('resource-publish',r.published?'Unpublish':'Publish',r.id,r.published?'secondary':'success')+button('resource-delete','Remove',r.id,'danger'):'')+'</div></article>').join(''));}
 function scoreboard(){return LCPCOrganizerScoreboards.render('live');}
 function clarifications(){const rows=state.data.clarifications.filter(c=>!c.deleted).sort((a,b)=>b.number-a.number);return '<div class="split-heading"><div><h2>Clarifications</h2><p>Answer team questions or send an announcement to all participants.</p></div>'+(manage()?button('announce','New announcement','','primary'):'')+'</div>'+rows.map(c=>'<article class="panel" data-row-card><div class="panel-heading"><div><h3>#'+c.number+' · '+esc(c.problem)+'</h3><small>'+esc(c.team)+' · '+(c.all?'Sent to all teams':'Team question')+'</small></div><span class="badge '+(c.answered?'accepted':'pending')+'">'+(c.answered?'Answered':'Awaiting reply')+'</span></div><p>'+esc(c.question)+'</p>'+(c.answer?'<div class="review-note">'+esc(c.answer)+'</div>':'')+(manage()?button('clarification-answer','Reply',c.site+'-'+c.number):'')+'</article>').join('');}
 function reviewHelp(){return '<p class="hint">Human review: open a submission row, inspect the summary and Details, then choose Accept solution, Reject / choose verdict, or confirm the automatic verdict. Confirming an automatic Wrong Answer rejects the solution. A reason is required and every decision is logged.</p>';}
 function judging(){const j=state.data.judging||{},pending=state.data.runs.filter(r=>!r.deleted&&!r.final&&!r.testAccount&&/^Awaiting human/.test(r.workflowState||''));return panel('Pending human review ('+pending.length+')',reviewHelp()+runTable(pending))+panel('Judging workflow','<p class="hint">Current mode: <strong>'+esc(workflowLabels[j.mode]||'Loading')+'</strong>. A provisional automatic result remains pending until a human final verdict in approval mode.</p>'+(owner()?'<form id="workflow-form"><label>Workflow for all problems<select name="mode">'+(j.mode==='mixed'?option('mixed','Mixed per-problem settings','mixed'):'')+Object.entries(workflowLabels).filter(([mode])=>mode!=='mixed').map(([mode,label])=>option(mode,label,j.mode)).join('')+'</select></label><p class="hint">Pause the contest and finalize pending submissions before changing the workflow. Changes apply to future submissions; existing final results stay recorded. In Human only mode, the administrator chooses the final verdict; no automatic execution is queued. Automatic + human approval keeps preliminary results out of standings and team verdict notifications.</p><div class="form-actions"><button class="primary">Review workflow change</button></div></form>':'<p class="hint">Only a dashboard owner can change the judging workflow.</p>')+((j.preliminaryResultsCounted||j.preliminaryNotifications)?'<p class="error">Native preliminary scoring or notifications are currently enabled. Applying a dashboard workflow disables both.</p>':''));}
 function controls(){const c=state.data.contest;return LCPCContests.runtime(state.contests,{owner:owner(),button,selected:state.data.system.contestId})+(state.data.system.contestStatus==='draft'?panel('Draft duration & ranking','<p class="hint">Duration: '+clock(c.lengthSeconds)+'. Penalty is configured before activation.</p>'+button('draft-settings','Edit duration & penalty',state.data.system.contestId)):'')+panel('Contest clock','<div class="stats"><div class="stat"><span>Remaining</span><strong>'+clock(c.remainingSeconds)+'</strong></div><div class="stat"><span>Elapsed</span><strong>'+clock(c.elapsedSeconds)+'</strong></div><div class="stat"><span>Duration</span><strong>'+clock(c.lengthSeconds)+'</strong></div><div class="stat"><span>Status</span><strong>'+(c.running?'Running':'Paused')+'</strong></div></div>'+(manage()&&state.data.system.contestStatus==='active'?'<div class="resource-actions">'+button('clock-start','Start / resume','','success')+button('clock-pause','Pause clock','','danger')+button('clock-extend','Add time')+'</div>':'<p class="hint">Start the contest server before using the clock controls.</p>'),'Clock actions change the live PC² contest and require explicit confirmation.')+panel('Contest configuration',manage()?'<form id="contest-form"><div class="form-grid">'+field('title','Contest title',c.title,'text','required maxlength="200"')+field('shortName','Short name',c.shortName,'text','required maxlength="80"')+(state.timezones?LCPCSchedule.render(state.timezones,state.data.system.schedulePreferences):'<p class="hint">Loading countries and time zones…</p>')+field('freezeRemaining','Freeze begins with this much time remaining',c.freezeRemaining,'text','required placeholder="HH:MM:SS"')+check('thawed','Release frozen public results',c.thawed)+'</div><div class="form-actions"><button class="primary">Review changes</button></div></form>':'<p class="hint">Your account has read-only access.</p>')+panel('Runtime','<dl class="status-list"><dt>Dashboard access</dt><dd>'+esc(state.data.system.scope)+'</dd><dt>Judge engine</dt><dd>PC² / isolated Linux</dd><dt>Languages</dt><dd>'+state.data.languages.filter(l=>l.active).map(l=>esc(l.name)).join('<br>')+'</dd><dt>Time zone</dt><dd>'+esc(state.data.system.timezone)+'</dd></dl>');}
 function security(){if(!state.security)return '<div class="panel empty">Loading security data…</div>';const s=state.security;return '<div class="split-heading"><div><h2>Security & activity</h2><p>Authentication, access denials, uploads and contest actions are recorded without passwords or source code.</p></div>'+button('user-create','Add dashboard user','','primary')+'</div><div class="review-note">Audit chain: <strong>'+(s.integrity.valid?'Verified · '+s.integrity.entries+' entries':'INTEGRITY FAILURE')+'</strong> · Sessions expire after 30 minutes idle or 8 hours total.</div>'+panel('Security alerts',s.alerts.filter(a=>!a.acknowledged).map(a=>'<div class="security-alert '+(a.severity==='error'?'error':'')+'"><p>'+esc(a.message)+'</p><small>'+date(a.created)+'</small> '+button('alert-ack','Acknowledge',a.id)+'</div>').join('')||'<p class="hint">No unacknowledged alerts.</p>')+panel('Dashboard users',table(['Username','Role','Two-step verification','Access',''],s.users.map(u=>'<tr><td>'+esc(u.username)+'</td><td>'+esc(u.role)+'</td><td>'+(u.totpEnabled?'Enabled':'Not enabled')+'</td><td>'+(u.enabled?'Enabled':'Disabled')+'</td><td>'+(u.enabled&&u.username!==state.user.username?button('user-disable','Disable',u.username,'danger'):'')+'</td></tr>')))+panel('Active sessions',table(['User','IP / access','Created','Last activity',''],s.sessions.map(x=>'<tr><td>'+esc(x.username)+'</td><td>'+esc(x.peer||'127.0.0.1')+' · '+esc(x.channel||'local')+'</td><td>'+date(x.created)+'</td><td>'+date(x.seen)+'</td><td>'+button('session-revoke','Revoke',x.id,'danger')+'</td></tr>')))+panel('Audit trail',table(['Time','Actor','Event','Outcome','Details'],s.events.map(e=>'<tr><td>'+date(e.created)+'</td><td>'+esc(e.actor)+'</td><td>'+esc(e.event)+'</td><td>'+esc(e.outcome)+'</td><td title="'+esc(e.details)+'">'+esc(e.details)+'</td></tr>')));}
 function account(){return (state.user.mustChange?'<div class="review-note"><strong>Change your temporary password before continuing.</strong> Use a unique password of at least 16 characters.</div>':'')+panel('Change password','<form id="password-form"><div class="form-grid">'+field('current','Current password','','password','required autocomplete="current-password"')+field('password','New password','','password','required minlength="16" maxlength="128" autocomplete="new-password"')+field('repeat','Repeat new password','','password','required minlength="16" autocomplete="new-password"')+(state.user.totpEnabled?field('code','Authenticator code','','text','required pattern="[0-9]{6}"'):'')+'</div><div class="form-actions"><button class="primary">Change password & sign out</button></div></form>')+(!state.user.mustChange?panel('Two-step verification',state.user.totpEnabled?'<p class="hint">An authenticator code is required when signing in.</p>'+button('totp-disable','Disable verification','','danger'):'<p class="hint">Add a six-digit authenticator code to your dashboard login.</p>'+button('totp-setup','Set up authenticator','','primary')):'');}

 function contests(){return LCPCContests.render(state.contests,{owner:owner(),button,table,date,selected:state.data.system.contestId});}
 function exports(){return LCPCContests.exportsView(state.contests,{owner:owner(),button,table,date,selected:state.data.system.contestId});}
 function render(){
  if(!state.user)return;
  LCPCParticipantActivity.dispose();LCPCOrganizerScoreboards.dispose();LCPCParticipantIdentityEditor.dispose();state.scheduleEditor?.dispose();state.scheduleEditor=null;
  const scroll=[window.scrollX,window.scrollY],tables=Array.from(document.querySelectorAll('.table-wrap')).map(e=>[e.scrollLeft,e.scrollTop]);
  navigation();$('section-title').textContent=sections.find(x=>x[0]===state.tab)?.[2]||'Overview';
  const view=activeView();let body='';
  if(state.tab==='account')body=account();
  else if(state.tab==='guide')body=LCPCGuide.guide();
  else if(state.tab==='about')body=LCPCGuide.about();
  else if(state.data){
   if(view==='public-scoreboard')body=LCPCOrganizerScoreboards.render('public');
   else if(view==='activity')body=LCPCParticipantActivity.render(state.data);
   else if(view==='team-connections')body=LCPCTeamConnections.render(state.data);
   else if(view==='remote-access')body=LCPCRemoteAccess.render();
   else if(view==='dashboard-branding')body=LCPCDashboardBranding.render(state.data);
   else if(view==='learning-reports')body=LCPCLearningReports.render();
   else if(view==='participant-identity')body=LCPCParticipantIdentityEditor.render(state.data);
   else if(view==='participant-test')body=LCPCParticipantTest.render(state.data);
   else if(view!=='main')body=LCPCAdministrator.render({owner:owner(),status:state.data.system.contestStatus,section:view,embedded:true});
   else body=({overview,contests,exports,runs,teams,problems,resources,scoreboard,clarifications,controls,judging,security}[state.tab]||overview)();
  }else body='<div class="panel empty">Connecting to PC²…</div>';
  $('content').innerHTML=sectionTabs()+body;
  Array.from(document.querySelectorAll('.table-wrap')).forEach((e,i)=>{if(tables[i]){e.scrollLeft=tables[i][0];e.scrollTop=tables[i][1];}});
  if(state.tab==='controls'&&view==='main'&&state.timezones&&$('content').querySelector('#contest-form'))state.scheduleEditor=LCPCSchedule.mount($('content').querySelector('#contest-form'),{catalog:state.timezones,prefs:state.data.system.schedulePreferences,instant:state.data.contest.scheduledStart,request:data=>api('schedule/preview',data)});
  if($('platform-guide'))LCPCGuide.mount($('platform-guide'));
  if($('learning-reports'))LCPCLearningReports.mount($('learning-reports'),nativeContext());
  if($('team-connections'))LCPCTeamConnections.mount($('team-connections'),nativeContext());
  if($('remote-access'))LCPCRemoteAccess.mount($('remote-access'),nativeContext());
  if($('dashboard-branding'))LCPCDashboardBranding.mount($('dashboard-branding'),nativeContext());
  if($('participant-identity'))LCPCParticipantIdentityEditor.mount($('participant-identity'),nativeContext());
  if($('participant-test'))LCPCParticipantTest.mount($('participant-test'),nativeContext());
  if($('participant-activity'))LCPCParticipantActivity.mount($('participant-activity'),{...nativeContext(),date,table,openSubmission:(site,number)=>action('run-details',site+'-'+number)});
  if($('organizer-scoreboard'))LCPCOrganizerScoreboards.mount($('organizer-scoreboard'),nativeContext());
  if($('native-admin'))LCPCAdministrator.mount($('native-admin'),nativeContext());
  window.scrollTo(...scroll);
 }

 function dialog(title,html,onSubmit){$('modal-title').textContent=title;$('modal-content').innerHTML=html;if(!document.querySelector('dialog[open]'))$('modal').showModal();const form=$('modal-content').querySelector('form');if(form&&onSubmit)form.addEventListener('submit',async event=>{event.preventDefault();const submit=form.querySelector('button[type=submit]')||form.querySelector('button');submit.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)),form);}catch(error){notice(error.message,true);}finally{submit.disabled=false;}});}
 function closeModal(){$('modal').close();}
 function confirmAction(title,description,action){dialog(title,'<p class="hint">'+esc(description)+'</p><form>'+field('confirmation','Type CONFIRM to continue','','text','required pattern="CONFIRM" autocomplete="off"')+'<div class="form-actions"><button type="submit" class="primary">Confirm action</button></div></form>',async()=>{await action();closeModal();notice('Change saved.');await refresh();});}
 function operation(name,args,description){confirmAction('Confirm contest action',description,()=>api('operation',{operation:name,args,confirm:'CONFIRM'}));}
 function formDialog(title,html,callback){dialog(title,'<form>'+html+'<div class="form-actions"><button type="submit" class="primary">Review changes</button></div></form>',callback);}
 async function downloadPost(path,data,name){return LCPCDownloads.transfer('/api/'+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.user.csrf},body:JSON.stringify({...data,contestId:state.data?.system?.contestId||state.contests?.selected})},name);}
 async function downloadResource(id){const row=state.data.resources.find(r=>r.id===id);return LCPCDownloads.transfer('/api/resources/'+id+'/download',{credentials:'same-origin'},row.filename);}
 function saveBlob(blob,name){return LCPCDownloads.save(blob,name);}
 function file64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
 async function action(name,id){const d=state.data;
  if(name==='review-queue'){state.tab='runs';state.views.runs='main';state.filters={verdict:'review'};render();window.scrollTo(0,0);return;}
  if(name==='server-controls-open'){state.tab='controls';state.views.controls='main';render();window.scrollTo(0,0);return;}
  if(name==='participant-test-open'){state.tab='system';state.views.system='participant-test';render();window.scrollTo(0,0);return;}
  if(name==='contest-recover')confirmAction('Recover contest server','Resume this interrupted startup? Existing teams, credentials and results are retained. The contest clock stays paused.',()=>api('contests/recover',{id,confirm:'CONFIRM'}));
  if(name==='contest-open'){await api('contests/select',{id});state.filters={};await refresh();state.tab='overview';render();}
  if(name==='contest-create')formDialog('New Contest','<p class="review-note">Create a separate draft. No teams, passwords, submissions or results are copied. The current contest remains active.</p><div class="form-grid">'+field('title','Contest title','','text','required maxlength="200"')+field('shortName','Short name','','text','required maxlength="80"')+field('slug','Unique contest ID','','text','required pattern="[a-z0-9][a-z0-9-]{0,45}" placeholder="omu-2027"')+field('durationMinutes','Duration in minutes',300,'number','required min="1" max="1440"')+field('penaltyMinutes','Penalty per unsuccessful attempt (minutes)',20,'number','required min="0" max="120"')+'<label>Judging workflow<select name="workflow">'+option('automatic','Automatic only')+option('review','Automatic + human approval')+option('human','Human only')+'</select></label><label>Starting content<select name="copyProblems">'+option('false','Empty contest')+option('true','Copy problems and judge data from this workspace')+'</select></label>'+check('copyResources','Copy statement PDFs, booklets and supporting resources as drafts',false)+'</div>',(form,element)=>confirmAction('Create contest draft','Create '+form.title+' as an independent draft? The current contest will remain active.',async()=>{await api('contests/create',{...form,durationMinutes:Number(form.durationMinutes),penaltyMinutes:Number(form.penaltyMinutes),copyProblems:form.copyProblems==='true',copyResources:element.elements.copyResources.checked,confirm:'CONFIRM'});state.tab='contests';}));
  if(name==='draft-settings')formDialog('Draft duration & penalty',field('durationMinutes','Duration (minutes)',Math.round(d.contest.lengthSeconds/60),'number','required min="1" max="1440"')+field('penaltyMinutes','Penalty (minutes)',d.contest.penaltyMinutes??20,'number','required min="0" max="120"'),form=>confirmAction('Update draft settings','Save duration and penalty for this draft?',()=>api('contests/draft-settings',{id,durationMinutes:Number(form.durationMinutes),penaltyMinutes:Number(form.penaltyMinutes),confirm:'CONFIRM'})));
  if(name==='contest-activate'){
   const active=state.contests?.active;
   if(active){dialog('Another contest is already active','<div class="review-note"><strong>Activation blocked.</strong> '+esc(state.contests.contests.find(c=>c.id===active)?.title||active)+' is active. Pause it, finalize pending submissions, then choose Deactivate. A paused clock still occupies the contest server.</div>');return;}
   confirmAction('Start contest server','Open participant access for '+id+'? This starts PC² services but leaves the contest clock paused. Only one contest may be active.',()=>api('contests/activate',{id,confirm:'CONFIRM'}));
  }
  if(name==='contest-release')confirmAction('Release stopped contest','Release the server reservation only if all PC² services are already stopped? This will be refused while any contest service is still running.',()=>api('contests/release-stopped',{id,confirm:'CONFIRM'}));
  if(name==='contest-deactivate')confirmAction('Stop contest server','Close participant access and cleanly stop PC² for '+id+'? Pause the clock and finalize pending submissions first. All results and source files are preserved.',()=>api('contests/deactivate',{id,confirm:'CONFIRM'}));
  if(name==='contest-archive'||name==='contest-unarchive'){const op=name.slice(8);confirmAction(op==='archive'?'Archive contest':'Unarchive contest','Change archive status for '+id+'? Data and results will be preserved.',()=>api('contests/'+op,{id,confirm:'CONFIRM'}));}
  if(name==='learning-open'){state.tab='exports';state.views.exports='learning-reports';render();}
  if(name==='contest-csv'||name==='contest-pdf')await downloadPost('contests/export',{id,format:name==='contest-csv'?'csv':'pdf'},id+'-report.'+(name==='contest-csv'?'zip':'pdf'));
  if(name==='contest-backup')confirmAction('Create encrypted full backup','Create a consistent archive of '+id+'? The contest must be deactivated. Download the recovery key separately and store both off this server.',()=>api('contests/backup',{id,confirm:'CONFIRM'}));
  if(name==='backup-download'){const [cid,backupId]=id.split('|');await downloadPost('contests/download-backup',{id:cid,backupId},cid+'-backup.zip');}
  if(name==='recovery-key')formDialog('Download private recovery key','<p class="review-note">This key decrypts all backups created for it. Store it separately from the archives, never with participant files.</p>'+field('password','Current owner password','','password','required autocomplete="current-password"')+(state.user.totpEnabled?field('code','Authenticator code','','text','required pattern="[0-9]{6}"'):'')+field('confirm','Type CONFIRM','','text','required pattern="CONFIRM"'),async form=>{await downloadPost('contests/recovery-key',{...form,id},'lcpc-recovery-key.zip');closeModal();notice('Recovery key downloaded. Keep it secure and separate.');});

  if(name==='clear-filters'){state.filters={};render();}
  if(name==='source'||name==='run-details'){
   const [site,number]=id.split('-'),cid=d.system.contestId,query=new URLSearchParams({site,number,contestId:cid}),r=d.runs.find(r=>r.site===Number(site)&&r.number===Number(number));
   dialog('Submission #'+number,'<p class="hint">'+esc(r?.teamName||'')+' · '+esc(r?.problem||'')+'</p><section id="submission-summary"><p class="hint">Loading judgement summary…</p></section><div id="submission-actions" class="form-actions"><a class="primary detail-page-link" target="_blank" rel="noopener noreferrer" href="/review.html?'+esc(query)+'">Details</a></div>');
   const pane=$('submission-summary');try{
    const value=await api('submission-review?'+query);if(!$('modal').open||$('submission-summary')!==pane)return;
    const evidence=value.evidence;pane.innerHTML=LCPCDiagnostics.summary(evidence);
    if(r)Object.assign(r,{automaticVerdict:evidence.automaticVerdict||'',final:evidence.final,verdict:evidence.verdict});
    if(owner())$('submission-actions').insertAdjacentHTML('afterbegin',(!evidence.final&&evidence.awaitingApproval&&evidence.automaticVerdict?button('run-approve','Confirm auto: '+status(evidence.automaticVerdict)[0],id,status(evidence.automaticVerdict)[1]==='accepted'?'success':'danger'):'')+button('run-accept','Accept solution',id,'success')+' '+button('run-reject','Reject / choose verdict',id,'danger')+' '+button('review-judgement',evidence.final?'Review final decision':'Choose final verdict',id)+' '+button('run-rejudge','Rejudge submission',id,'danger'));
   }catch(error){if($('submission-summary')===pane){pane.textContent=error.message;pane.className='error';}}
  }
  if(name==='run-approve'){const [site,number]=id.split('-'),r=d.runs.find(r=>r.number===Number(number)&&r.site===Number(site));if(!r?.automaticVerdict)throw new Error('Refresh the submissions before approving');formDialog('Approve automatic verdict · Run #'+number,'<p class="review-note">Provisional verdict: <strong>'+esc(status(r.automaticVerdict)[0])+'</strong>. Approval creates the final human verdict and releases it to the team and standings.</p><label>Approval reason<textarea name="reason" required minlength="8" maxlength="1000"></textarea></label>',form=>operation('run.approve',{number:Number(number),site:Number(site),expectedJudgement:r.automaticVerdict,reason:form.reason},'Approve the automatic verdict as the final human decision for run #'+number+'?'));}
  if(name==='run-rejudge'){const [site,number]=id.split('-');formDialog('Rejudge submission #'+number,'<label>Reason<textarea name="reason" required minlength="8" maxlength="1000"></textarea></label>',form=>operation('run.rejudge',{site:Number(site),number:Number(number),reason:form.reason},'Queue run #'+number+' for fresh judging? Its official result may change.'));}
  if(['review-judgement','run-accept','run-reject'].includes(name)){const [site,number]=id.split('-'),preferred=name==='run-accept'?d.judgements.find(j=>status(j.name)[1]==='accepted')?.name:name==='run-reject'?d.judgements.find(j=>status(j.name)[0]==='Wrong Answer')?.name:'';formDialog('Review judgement · Run #'+number,'<div class="review-note">This changes the official PC² judgement. A reason is required and the action is audited.</div><label>Final verdict<select name="judgement" required>'+option('','Choose a final verdict',preferred)+d.judgements.map(j=>option(j.name,j.name,preferred)).join('')+'</select></label><label>Review reason<textarea name="reason" required minlength="8" maxlength="1000"></textarea></label>',form=>operation('judgement',{site:Number(site),number:Number(number),judgement:form.judgement,reason:form.reason},'Apply the selected judgement to run #'+number+'?'));}
  if(name==='team-create')formDialog('Add team',field('name','Display name','','text','required maxlength="200"')+field('password','Initial team password','','password','required minlength="16" maxlength="128"'),form=>operation('team.create',form,'Create a new team account in PC²?'));
  if(name==='team-edit'){const t=d.teams.find(t=>t.login===id);formDialog('Edit '+id,field('name','Display name',t.name,'text','required maxlength="200"')+field('password','New password (leave blank to keep)','','password','minlength="16" maxlength="128"')+check('enabled','Allow team login',t.enabled)+check('visible','Show on public scoreboard',t.visible),(form,element)=>operation('team.update',{...form,login:id,enabled:element.elements.enabled.checked,visible:element.elements.visible.checked},'Update '+id+'? Changes apply to the live contest.'));}
  if(name==='problem-create')formDialog('Add judged problem','<p class="review-note">The contest must be paused. The new problem is created inactive; publish its statements and activate it when ready. Judge data is never shared with participants.</p><div class="form-grid">'+field('letter','Problem letter','','text','required pattern="[A-Z]{1,3}" maxlength="3"')+field('name','Problem title','','text','required maxlength="200"')+field('timeLimit','Time limit (seconds)',2,'number','required min="1" max="10"')+field('memoryLimit','Memory limit (MiB)',256,'number','required min="32" max="1024"')+balloonFields()+'<label class="wide">Sandbox / validator profile<select name="template">'+(d.problems.length?d.problems.map(p=>option(p.id,p.letter+' · '+p.name)).join(''):option('__default__','Standard isolated validator'))+'</select></label><label class="wide">Judge test ZIP<input type="file" name="tests" accept=".zip" required></label></div><p class="hint">ZIP containing paired files such as 01.in and 01.ans. Up to 250 pairs, 20 MiB compressed / 50 MiB total. Executables and custom validator uploads are not accepted.</p>',async(form,element)=>{const file=element.elements.tests.files[0];if(file.size>20*1024*1024)throw new Error('Archive exceeds 20 MiB');const base64=await file64(file);const args={letter:form.letter,name:form.name,timeLimit:Number(form.timeLimit),memoryLimit:Number(form.memoryLimit),colorName:form.colorName,colorRGB:form.colorRGB,template:form.template};confirmAction('Create judged problem','Create problem '+form.letter+' with the uploaded private judge tests?',()=>api('problems/create',{args,base64,confirm:'CONFIRM'}));});
  if(name==='problem-edit'){if(owner()&&d.system.contestStatus==='active'){await LCPCAdministrator.openEditor(nativeContext(),'problems',id);return;}const p=d.problems.find(p=>p.id===id);formDialog('Edit problem '+p.letter,'<div class="form-grid">'+field('name','Problem title',p.name,'text','required maxlength="200"')+field('timeLimit','Time limit (seconds)',p.timeLimit,'number','required min="1" max="10"')+field('memoryLimit','Memory limit (MiB)',p.memoryLimit,'number','required min="32" max="1024"')+balloonFields(p)+check('active','Active for participants',p.active)+'</div>',(form,element)=>{const args={...form,id,timeLimit:Number(form.timeLimit),memoryLimit:Number(form.memoryLimit),active:element.elements.active.checked};if(!p.colorName&&!form.colorName.trim()){delete args.colorName;delete args.colorRGB;}operation('problem.update',args,'Update the settings for '+p.letter+'? Existing judged submissions are not automatically rejudged.');});}
  if(name==='problem-resources'){state.tab='resources';state.filters.resourceProblem=id;render();}
  if(name==='upload'){const selected=state.filters.resourceProblem||d.problems[0]?.id||'__contest__';formDialog('Upload problem resource','<div class="form-grid"><label>Linked problem<select name="problem" required>'+option('__contest__','Contest booklet',selected)+d.problems.map(p=>option(p.id,p.letter+' · '+p.name,selected)).join('')+'</select></label><label>Resource type<select name="kind">'+option('statement','Problem statement',selected==='__contest__'?'booklet':'statement')+option('helper','Supporting file')+option('booklet','Contest booklet',selected==='__contest__'?'booklet':'statement')+'</select></label><label>Language<select name="language">'+option('en','English')+option('ar','Arabic')+option('both','Bilingual')+option('none','Not language-specific')+'</select></label>'+field('label','Participant-facing label','','text','required maxlength="200"')+'<label class="wide">File<input type="file" name="upload" required accept=".pdf,.txt,.csv,.json,.zip,.png,.jpg,.jpeg"></label></div><p class="hint">One file up to 20 MiB. Statements and booklets must be PDF. Supporting archives may contain data and documents only. The upload remains a draft until published.</p>',async(form,element)=>{const file=element.elements.upload.files[0];if(file.size>20*1024*1024)throw new Error('Maximum upload size is 20 MiB');await api('resources/upload',{problem:form.problem,kind:form.kind,language:form.language,label:form.label,filename:file.name,base64:await file64(file)});closeModal();notice('Uploaded as a draft. Review it before publishing.');await refresh();});const form=$('modal-content').querySelector('form');form.elements.problem.addEventListener('change',()=>{if(form.elements.problem.value==='__contest__')form.elements.kind.value='booklet';else if(form.elements.kind.value==='booklet')form.elements.kind.value='statement';});}
  if(name==='resource-trash'){const value=await api('resources/trash');dialog('Removed resources',value.resources.length?value.resources.map(r=>'<article class="resource-group"><h3>'+esc(r.label)+'</h3><p class="hint">'+esc(r.filename)+' · Version '+r.version+'</p>'+button('resource-restore','Restore as draft',r.id)+'</article>').join(''):'<p class="hint">No removed resources.</p>');}
  if(name==='resource-restore')confirmAction('Restore resource','Restore this resource as an unpublished draft?',()=>api('resources/restore',{id,confirm:'CONFIRM'}));
  if(name==='resource-download')await downloadResource(id);
  if(name==='resource-publish'){const r=d.resources.find(r=>r.id===id);confirmAction(r.published?'Unpublish resource':'Publish resource',r.published?'Remove this resource from participant access?':'Make '+r.label+' available to signed-in participants?',()=>api('resources/publish',{id,published:!r.published,confirm:'CONFIRM'}));}
  if(name==='resource-delete')confirmAction('Remove resource','Unpublish and remove this resource from the active catalog? The operation remains recorded in the audit log.',()=>api('resources/delete',{id,confirm:'CONFIRM'}));
  if(name==='clock-start')operation('clock.start',{},'Start or resume the contest clock and allow submissions according to PC² settings?');
  if(name==='clock-pause')operation('clock.pause',{},'Pause the live contest clock? Teams may be unable to submit while paused.');
  if(name==='clock-extend')formDialog('Extend contest time',field('minutes','Minutes to add',5,'number','required min="1" max="1440"'),form=>operation('clock.extend',{seconds:Number(form.minutes)*60},'Add '+form.minutes+' minutes to the current contest?'));
  if(name==='announce')formDialog('Announcement to all teams','<label>Message<textarea name="message" required maxlength="8000"></textarea></label>',form=>operation('announcement',{message:form.message},'Send this announcement to all contest teams?'));
  if(name==='clarification-answer'){const [site,number]=id.split('-');const c=d.clarifications.find(c=>c.number===Number(number)&&c.site===Number(site));formDialog('Reply to clarification #'+number,'<p class="review-note">'+esc(c.question)+'</p><label>Answer<textarea name="answer" required maxlength="8000">'+esc(c.answer)+'</textarea></label>'+check('all','Send answer to all teams',c.all),(form,element)=>operation('clarification.answer',{number:Number(number),site:Number(site),answer:form.answer,all:element.elements.all.checked},'Send this clarification answer?'));}
  if(name==='alert-ack'){await api('alerts/acknowledge',{id:Number(id)});await refresh();}
  if(name==='session-revoke')confirmAction('Revoke session','Sign out this dashboard session?',()=>api('sessions/revoke',{id}));
  if(name==='user-disable')confirmAction('Disable dashboard user','Disable '+id+' and revoke their dashboard sessions?',()=>api('users/disable',{username:id,confirm:'CONFIRM'}));
  if(name==='user-create')formDialog('Add dashboard user',field('username','Username','','text','required pattern="[a-z][a-z0-9_-]{2,31}"')+'<label>Role<select name="role">'+option('viewer','Viewer — read-only')+option('operator','Operator — contest and resources')+option('owner','Owner — security and judgement review')+'</select></label>'+field('password','Temporary password','','password','required minlength="16" maxlength="128"'),async form=>{await api('users/create',form);closeModal();notice('User created. Password change is required at first login.');await refresh();});
  if(name==='totp-setup')formDialog('Verify your password',field('password','Current password','','password','required autocomplete="current-password"'),async credentials=>{const result=await api('totp/setup',credentials);dialog('Set up an authenticator','<form data-totp-setup><p class="hint">Scan this QR code with your authenticator app, then enter the six-digit code it shows. Account: '+esc(result.account)+'. Complete setup within five minutes. Keep this QR code and setup key private.</p><div class="totp-qr">'+result.qrSvg+'</div><details class="totp-manual"><summary>Cannot scan? Enter the setup key manually</summary><p class="hint">Choose a time-based (TOTP) account in your authenticator.</p><p class="session-secret">'+esc(result.secret)+'</p></details>'+field('code','Current six-digit code','','text','required inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}"')+'<div class="form-actions"><button type="submit" class="primary">Enable two-step verification</button></div></form>',async form=>{await api('totp/enable',form);state.user=await api('me');closeModal();notice('Two-step verification enabled.');render();});});
  if(name==='totp-disable')formDialog('Disable two-step verification',field('password','Current password','','password','required')+field('code','Authenticator code','','text','required pattern="[0-9]{6}"'),async form=>{await api('totp/disable',form);state.user=await api('me');closeModal();notice('Two-step verification disabled.');render();});
 }
 $('login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button');button.disabled=true;$('login-error').textContent='';try{signedIn(await api('login',Object.fromEntries(new FormData(form))));form.reset();}catch(error){$('login-error').textContent=error.message;}finally{button.disabled=false;}});
 $('navigation-search').addEventListener('input',navigation);
 $('quick-clock').addEventListener('click',()=>{state.tab='controls';state.views.controls='main';render();window.scrollTo(0,0);});
 $('navigation').addEventListener('click',async event=>{const target=event.target.closest('[data-tab]');if(!target)return;state.tab=target.dataset.tab;if(state.tab==='security'){try{state.security=await api('security');}catch(error){notice(error.message,true);}}render();window.scrollTo(0,0);});
 $('content').addEventListener('click',event=>{const tab=event.target.closest('[data-section-view]');if(!tab)return;const requested=tab.dataset.sectionView;if(!LCPCNavigation.available(state.tab,owner()).some(([id])=>id===requested))return;state.views[state.tab]=requested;render();window.scrollTo(0,0);});
 document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;target.disabled=true;try{await action(target.dataset.action,target.dataset.id);}catch(error){notice(error.message,true);}finally{target.disabled=false;}});
 $('content').addEventListener('input',event=>{const form=event.target.closest('#contest-form');if(form)form.dataset.dirty='true';});$('content').addEventListener('change',event=>{const form=event.target.closest('#contest-form');if(form)form.dataset.dirty='true';});
 $('content').addEventListener('submit',async event=>{event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));try{if(form.id==='run-filters'){state.filters={...state.filters,...data};render();}if(form.id==='resource-filter'){state.filters.resourceProblem=data.resourceProblem;render();}if(form.id==='workflow-form')operation('judging.workflow',{mode:data.mode},'Set '+(workflowLabels[data.mode]||data.mode)+' for all problems? This affects future submissions. The contest must be paused and all pending submissions finalized.');if(form.id==='contest-form'){if(!state.scheduleEditor)throw new Error('Time zone options are still loading');const schedule=await state.scheduleEditor.value();operation('contest.update',{title:data.title,shortName:data.shortName,freezeRemaining:data.freezeRemaining,thawed:form.elements.thawed.checked,...schedule.args},'Apply contest and freeze settings? Scheduled start: '+schedule.description+'.');}if(form.id==='password-form'){if(data.password!==data.repeat)throw new Error('New passwords do not match');await api('password',{current:data.current,password:data.password,code:data.code||''});signedOut();notice('Password changed. Sign in with the new password.');}}catch(error){notice(error.message,true);}});
 $('refresh').addEventListener('click',()=>refresh());$('logout').addEventListener('click',async()=>{try{await api('logout',{});}catch(_){}signedOut();});$('modal-close').addEventListener('click',closeModal);
 $('modal').addEventListener('close',()=>{if($('modal-content').querySelector('[data-totp-setup]'))$('modal-content').replaceChildren();});
 setInterval(()=>{if(!document.hidden&&!document.querySelector('dialog[open]'))refresh(true);},10000);
 LCPCRowDetails.mount({getDetails:rowDetails});
 LCPCDashboardBranding.load();
 api('me').then(signedIn).catch(()=>signedOut());
})();
